new_att <- attempts
new_att$mouse <- factor(paste0("new_", attempts$mouse))
set.seed(1)
yrep_wire <- posterior_predict(fit_wire_logit, newdata = new_att, allow_new_levels = TRUE,
                               sample_new_levels = "gaussian", ndraws = 1000)
band_new <- count_band(yrep_wire, new_att$mouse, "Logistic with levels")
```
